typedef float vm_num_t;

class entity;

class entity_list
{
  entity **start;
  entity **finish;
  entity **end_of_storage;

public:
  unsigned int size() const { return finish - start; }
  entity *operator[](unsigned int index) { return start[index]; }
};

class vm_stack
{
  char padding[8];

public:
  char *SP;
  void *thread;

  void pop(int n) { SP -= n; }
  bool push(const char *, int);
};

extern void error(const char *, ...);

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual bool operator()(vm_stack &, entry_t) = 0;
  };
};

class slf_entity_list_get_index_t :
  public script_library_class::function
{
public:
  struct parms_t
  {
    entity_list *me;
    vm_num_t index;
  };

  virtual bool operator()(vm_stack &, entry_t);
};

bool slf_entity_list_get_index_t::operator()(
  vm_stack &stack, entry_t)
{
  stack.pop(sizeof(parms_t));
  parms_t *parms = (parms_t *)stack.SP;

  if ((parms->index >= parms->me->size()) || (parms->index < 0))
    error("Index out of range %d", (int)parms->index);

  entity *result = (*parms->me)[(int)parms->index];
  stack.push((char *)&result, sizeof(result));
  return true;
}
